const updateCouponClickCounts = `-- name: UpdateCouponClickCounts :exec
UPDATE coupons c
SET total_clicks = (
 SELECT COUNT(*)::int FROM coupon_events ce
 WHERE ce.coupon_id = c.id AND ce.event_type = 'click'
),
 updated_at = now()
WHERE EXISTS (
 SELECT 1 FROM coupon_events ce
 WHERE ce.coupon_id = c.id AND ce.event_type = 'click'
)
`

